\version "2.27.2"
% automatically converted by musicxml2ly from 33h-Spanners-Glissando.xml
\pointAndClickOff

\header {
  texidoc = "All different types of glissando defined in MusicXML. The first two
    and a half measures contain <glissando> elements with various ‘line-type’
    attributes, the rest contains <slide> elements (also with various
    ‘line-type’ attributes)."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative g' {
  \clef "treble" \key c \major \once \omit Staff.TimeSignature \once \override
  Glissando.style = #'trill g4 \glissando f'4 g,4 \glissando f'4 | % 1
  \once \override Glissando.style = #'dashed-line g,4 \glissando f'4 \once
  \override Glissando.style = #'dotted-line g,4 \glissando f'4 | % 2
  \once \override Glissando.style = #'trill g,4 \glissando f'4 g,4 \glissando f'4
  | % 3
  g,4 \glissando f'4 \once \override Glissando.style = #'dashed-line g,4
  \glissando f'4 | % 4
  \once \override Glissando.style = #'dotted-line g,4 \glissando f'4 \once
  \override Glissando.style = #'trill g,4 \glissando f'4 \bar "|."
}

PartPOneVoiceOneLyricsOne = \lyricmode {
  \set ignoreMelismata = ##t
  \set includeGraceNotes = ##t
  default glissando solid "(+text)" dashed \skip1 dotted \skip1 wavy \skip1
  default slide solid "(+text)" dashed \skip1 dotted \skip1 wavy \skip1
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
        \new Lyrics \lyricsto "PartPOneVoiceOne" {
          \PartPOneVoiceOneLyricsOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
